function evalQuintic(p0, v0, a0, p1, v1, a1, T, t) {
  const s = Math.max(0, Math.min(1, t / T));
  const T2 = T * T;
  const c0 = p0;
  const c1 = v0 * T;
  const c2 = 0.5 * a0 * T2;
  const dp = p1 - (c0 + c1 + c2);
