function sampleQuintic(p0, v0, a0, p1, v1, a1, T, t) {
  const s = Math.max(0, Math.min(1, t / T));
  const T2 = T * T;
  const c0 = p0, c1 = v0 * T, c2 = 0.5 * a0 * T2;
  const dp = p1 - (c0 + c1 + c2), dv = v1 * T - (c1 + 2 * c2), da = a1 * T2 - 2 * c2;
  const c3 = 10 * dp - 4 * dv + 0.5 * da, c4 = -15 * dp + 7 * dv - da, c5 = 6 * dp - 3 * dv + 0.5 * da;
  const s2 = s * s, s3 = s2 * s, s4 = s3 * s, s5 = s4 * s;
  return {
    pos: c0 + c1 * s + c2 * s2 + c3 * s3 + c4 * s4 + c5 * s5,
    vel: (c1 + 2 * c2 * s + 3 * c3 * s2 + 4 * c4 * s3 + 5 * c5 * s4) / T,
    acc: (2 * c2 + 6 * c3 * s + 12 * c4 * s2 + 20 * c5 * s3) / T2,
    jerk: (6 * c3 + 24 * c4 * s + 60 * c5 * s2) / (T2 * T),
  };
}
