  { t: 2.7, p: [-1.15, 1.05, -0.85], v: [0.45, 0.20, 0.35], a: [0, 0, 0] },
  { t: 5.5, p: [0.15, 1.40, 0.25], v: [0.45, 0.0, 0.35], a: [0, 0, 0] },
  { t: 8.3, p: [1.35, 1.05, 1.05], v: [0.38, -0.25, 0.28], a: [0, 0, 0] },
  { t: 11.2, p: [2.05, 0.082, 1.65], v: [0, 0, 0], a: [0, 0, 0] },
];
let maxA = 0, maxAz = 0, maxJ = 0;
for (let seg = 0; seg < 4; seg++) {
  const w0 = wps[seg], w1 = wps[seg + 1], T = w1.t - w0.t;
  for (let t = 0; t <= T; t += 0.01) {
    const rx = sampleQuintic(w0.p[0], w0.v[0], w0.a[0], w1.p[0], w1.v[0], w1.a[0], T, t);
    const ry = sampleQuintic(w0.p[1], w0.v[1], w0.a[1], w1.p[1], w1.v[1], w1.a[1], T, t);
    const rz = sampleQuintic(w0.p[2], w0.v[2], w0.a[2], w1.p[2], w1.v[2], w1.a[2], T, t);
    maxA = Math.max(maxA, Math.hypot(rx.acc, ry.acc, rz.acc));
    maxAz = Math.max(maxAz, Math.abs(rz.acc));
    maxJ = Math.max(maxJ, Math.hypot(rx.jerk, ry.jerk, rz.jerk));
  }
}
