        if (norm(simState.vel) > TASK.contactCrashSpeed) simState.reason = 'wall or ceiling crash';
        simState.pos.x = clamp(simState.pos.x, TASK.room.minX + TASK.bodyRadius, TASK.room.maxX - TASK.bodyRadius);
        simState.pos.z = clamp(simState.pos.z, TASK.room.minZ + TASK.bodyRadius, TASK.room.maxZ - TASK.bodyRadius);
        simState.pos.y = Math.min(simState.pos.y, TASK.room.height - TASK.bodyHeight);
        simState.vel.x = 0; simState.vel.z = 0; simState.vel.y = Math.min(simState.vel.y, 0);
      }
      if (simState.pos.y <= TASK.bodyHeight) {
        if (simState.airborne && (norm(simState.vel) > TASK.contactCrashSpeed || Math.max(Math.abs(simState.att.roll), Math.abs(simState.att.pitch)) > TASK.landingTilt * 2)) simState.reason = 'floor crash';
