          const fits = dy + TASK.bodyHeight <= half && dz + TASK.bodyRadius <= half;
          const overlapsFrame = dy <= outer + TASK.bodyHeight && dz <= outer + TASK.bodyRadius && !fits;
          if (overlapsFrame) simState.reason = 'gate frame collision';
          if (i === simState.gateIndex && old.x < x && simState.pos.x >= x && fits) simState.gateIndex++;
        }
      }
      const error = Math.hypot(simState.pos.x - PAD.centre.x, simState.pos.z - PAD.centre.z);
      if (simState.gateIndex === GATES.length && error <= TASK.landingRadius && simState.pos.y <= TASK.bodyHeight + 0.025 &&
          norm(simState.vel) < TASK.landingSpeed && Math.max(Math.abs(simState.att.roll), Math.abs(simState.att.pitch)) < TASK.landingTilt) simState.landedFor += dt;
      else simState.landedFor = 0;
      if (simState.landedFor >= TASK.landingHold && !simState.reason) simState.reason = 'landed';
    }
    return simState;
  };
}

let pass = 0, fails = [];
for (let seed = 0; seed < 500; seed++) {
  const step = makeStep(seed);
