      x: (sumMotors * dir.x + TASK.linearDrag * (curWind.x - v.x)) / m,
      y: (sumMotors * dir.y + TASK.linearDrag * (curWind.y - v.y)) / m - TASK.gravity,
      z: (sumMotors * dir.z + TASK.linearDrag * (curWind.z - v.z)) / m,
