    p: c0 + c1 * s + c2 * s2 + c3 * s3 + c4 * s4 + c5 * s5,
    v: (c1 + 2 * c2 * s + 3 * c3 * s2 + 4 * c4 * s3 + 5 * c5 * s4) / T,
    a: (2 * c2 + 6 * c3 * s + 12 * c4 * s2 + 20 * c5 * s3) / T2,
