    const kpZ = onPadSegment ? 12.0 : 24.0, kvZ = onPadSegment ? 6.5 : 9.6;

    const ex = ref.p.x - p.x, ey = ref.p.y - p.y, ez = ref.p.z - p.z;
    const evx = ref.v.x - v.x, evy = ref.v.y - v.y, evz = ref.v.z - v.z;
    const eax = ref.a.x - curAcc.x, eay = ref.a.y - curAcc.y, eaz = ref.a.z - curAcc.z;

    const ades = {
      x: clamp(ref.a.x + kpX * ex + kvX * evx, -8.5, 8.5),
      y: clamp(ref.a.y + kpY * ey + kvY * evy, -6.0, 8.0),
      z: clamp(ref.a.z + kpZ * ez + kvZ * evz, -8.5, 8.5),
    };
    const jdes = {
      x: ref.j.x + kpX * evx + 0.55 * kvX * eax,
      y: ref.j.y + kpY * evy + 0.55 * kvY * eay,
      z: ref.j.z + kpZ * evz + 0.55 * kvZ * eaz,
    };

    const FxW = m * ades.x - TASK.linearDrag * (wEff.x - v.x);
    let Fy = Math.max(2.0, m * (ades.y + TASK.gravity) - TASK.linearDrag * (wEff.y - v.y));
    const FzW = m * ades.z - TASK.linearDrag * (wEff.z - v.z);

    // If horizontal force demand exceeds what Fy * tan(0.55) can provide during gate approach, boost Fy slightly within gate y-margin
    if (!onPadSegment && Math.abs(ey) < 0.08) {
      const Fhoriz = Math.hypot(FxW, FzW);
      const minFyForHoriz = Fhoriz / Math.tan(0.56);
      if (minFyForHoriz > Fy) {
        Fy = Math.min(Fy + 1.8, minFyForHoriz);
      }
    }

    const dFxW = m * jdes.x - TASK.linearDrag * (dwEff.x - ades.x);
    const dFy = m * jdes.y - TASK.linearDrag * (dwEff.y - ades.y);
    const dFzW = m * jdes.z - TASK.linearDrag * (dwEff.z - ades.z);

    const Fx = cy * FxW - sy * FzW;
    const Fz = sy * FxW + cy * FzW;
    const dFx = cy * dFxW - sy * dFzW - rates.yaw * Fz;
    const dFz = sy * dFxW + cy * dFzW + rates.yaw * Fx;

    const Fxy2 = Fx * Fx + Fy * Fy;
    const Fxy = Math.sqrt(Fxy2);
    const Fmag2 = Fxy2 + Fz * Fz;
    const dFxy = (Fx * dFx + Fy * dFy) / Fxy;

    const padDist = Math.hypot(p.x - PAD.centre.x, p.z - PAD.centre.z);
    const settlingOnPad = simState.gateIndex === 3 && (t - timeShift >= 10.5) && padDist < 0.11 && norm(v) < 0.35;
    const rawPitchDes = Math.atan2(Fx, Fy);
    const rawRollDes = -Math.atan2(Fz, Fxy);
    const maxTilt = (settlingOnPad && Math.max(Math.abs(rawPitchDes), Math.abs(rawRollDes)) < 0.21) ? 0.17 : 0.68;

    const pitchDes = clamp(rawPitchDes, -maxTilt, maxTilt);
    const pitchRateDes = clamp((Fy * dFx - Fx * dFy) / Fxy2, -6, 6);

    const rollDes = clamp(rawRollDes, -maxTilt, maxTilt);
    const rollRateDes = clamp(-(Fxy * dFz - Fz * dFxy) / Fmag2, -6, 6);

    const inertia = TASK.inertia * m / TASK.baseMass;
    const moment = (sign) => simState.motors.reduce((a, f, i) => a + f * sign[i], 0);
    const alphaRoll = TASK.arm * moment(MOTOR_Z) / inertia - 0.4 * rates.roll;
    const alphaPitch = -TASK.arm * moment(MOTOR_X) / inertia - 0.4 * rates.pitch;

    const kAttP = 85, kAttD = 16, kAttA = 0.30;
    const tauRollSym = inertia * (kAttP * (rollDes - att.roll) + kAttD * (rollRateDes - rates.roll) - kAttA * alphaRoll);
    const tauPitchSym = inertia * (kAttP * (pitchDes - att.pitch) + kAttD * (pitchRateDes - rates.pitch) - kAttA * alphaPitch);
    const tauYawSym = inertia * (-14 * att.yaw - 6 * rates.yaw);

    const cosTilt = Math.max(0.50, Math.cos(att.roll) * Math.cos(att.pitch));
    const Fdes = Fy / cosTilt;
    const dFdes = dFy / cosTilt + Fdes * (Math.tan(att.pitch) * rates.pitch + Math.tan(att.roll) * rates.roll);
    const Tsym = clamp(Fdes + lag * dFdes + 0.40 * (Fdes - sumMotors), 0.2, 15.5);

    const dtSub = TASK.dt / TASK.substeps;
    const torqueBounds = (axis) => {
      const I0 = simState.integral[axis], r0 = rates[axis], a0 = att[axis];
      const eMin = -0.6 - a0, eMax = 0.6 - a0;
      const Imin = clamp(I0 + eMin * dtSub, -0.35, 0.35);
      const Imax = clamp(I0 + eMax * dtSub, -0.35, 0.35);
      return {
        min: inertia * (65 * eMin - 13 * r0 + 22 * Imin),
        max: inertia * (65 * eMax - 13 * r0 + 22 * Imax),
      };
    };
    const bRoll = torqueBounds('roll');
    const bPitch = torqueBounds('pitch');

    const w = params.weakMotor;
    const fw = clamp(
      Tsym / 4 +
        clamp(tauRollSym, -0.12, 0.12) * MOTOR_Z[w] / (4 * TASK.arm) -
        clamp(tauPitchSym, -0.12, 0.12) * MOTOR_X[w] / (4 * TASK.arm) +
        tauYawSym * SPIN[w] / (4 * TASK.yawCoefficient),
      0,
      TASK.maxMotorThrust * (1 - params.weakness)
    );
    const deltaFull = (params.weakness / (1 - params.weakness)) * fw;

    const tauRollCmd = clamp(tauRollSym + TASK.arm * MOTOR_Z[w] * deltaFull, bRoll.min, bRoll.max);
    const tauPitchCmd = clamp(tauPitchSym - TASK.arm * MOTOR_X[w] * deltaFull, bPitch.min, bPitch.max);

    const deltaR = clamp(MOTOR_Z[w] * (tauRollCmd - tauRollSym) / TASK.arm, 0, deltaFull);
    const deltaP = clamp(-MOTOR_X[w] * (tauPitchCmd - tauPitchSym) / TASK.arm, 0, deltaFull);
    const deltaEff = Math.min(deltaFull, deltaR, deltaP);

    // Choose deltaY to unload weak motor w when roll or pitch saturates
    let deltaY = deltaEff;
    if (params.weakness > 0.01 && deltaEff < deltaFull - 1e-4) {
      deltaY = 4 * (deltaEff / params.weakness - fw) - 3 * deltaEff;
    }

    const thrustCmd = (Tsym + deltaEff) / 16.0;
    const tauYawCmd = tauYawSym + TASK.yawCoefficient * SPIN[w] * deltaY;

    const invertAxis = (axis, tauCmd) => {
      const u = tauCmd / inertia;
      const I0 = simState.integral[axis];
      const r0 = rates[axis], a0 = att[axis];
      let err = (u + 13 * r0 - 22 * I0) / (65 + 22 * dtSub);
      const I1 = clamp(I0 + err * dtSub, -0.35, 0.35);
      if (I1 !== I0 + err * dtSub) {
        err = (u + 13 * r0 - 22 * I1) / 65;
      }
      return a0 + err;
    };

    const action = {
      thrust: clamp(thrustCmd, 0, 1),
      roll: clamp(invertAxis('roll', tauRollCmd), -0.6, 0.6),
      pitch: clamp(invertAxis('pitch', tauPitchCmd), -0.6, 0.6),
      yawRate: clamp(rates.yaw + tauYawCmd / (8 * inertia), -2, 2),
    };

    for (let sub = 0; sub < 2 && !simState.reason; sub++) {
      const dt = 0.005, old = copy(simState.pos);
      const torque = {};
      for (const axis of ['roll', 'pitch']) {
        const error = action[axis] - simState.att[axis];
        simState.integral[axis] = clamp(simState.integral[axis] + error * dt, -0.35, 0.35);
        torque[axis] = inertia * (65 * error - 13 * simState.rates[axis] + 22 * simState.integral[axis]);
      }
      torque.yaw = inertia * 8 * (action.yawRate - simState.rates.yaw);
      for (let i = 0; i < 4; i++) {
        const desired = action.thrust * TASK.maxMotorThrust +
          torque.roll * MOTOR_Z[i] / (4 * TASK.arm) - torque.pitch * MOTOR_X[i] / (4 * TASK.arm) +
          torque.yaw * SPIN[i] / (4 * TASK.yawCoefficient);
        const target = clamp(desired, 0, TASK.maxMotorThrust) * (i === parameters.weakMotor ? 1 - params.weakness : 1);
        simState.motors[i] += (target - simState.motors[i]) * (1 - Math.exp(-dt / params.lag));
      }
      const sum = simState.motors.reduce((a, b) => a + b, 0);
      const mom = (sign) => simState.motors.reduce((a, f, i) => a + f * sign[i], 0);
      simState.rates.roll += (TASK.arm * mom(MOTOR_Z) / inertia - 0.4 * simState.rates.roll) * dt;
      simState.rates.pitch += (-TASK.arm * mom(MOTOR_X) / inertia - 0.4 * simState.rates.pitch) * dt;
      simState.rates.yaw += (TASK.yawCoefficient * mom(SPIN) / inertia - 0.4 * simState.rates.yaw) * dt;
      for (const axis of ['roll', 'pitch', 'yaw']) simState.att[axis] += simState.rates[axis] * dt;
      const bX = Math.sin(simState.att.pitch) * Math.cos(simState.att.roll), bZ = -Math.sin(simState.att.roll);
      const d = {
        x: Math.cos(simState.att.yaw) * bX + Math.sin(simState.att.yaw) * bZ,
        y: Math.cos(simState.att.pitch) * Math.cos(simState.att.roll),
        z: -Math.sin(simState.att.yaw) * bX + Math.cos(simState.att.yaw) * bZ,
      };
      const wind = copy(params.baseWind);
      for (const gust of params.gusts) if (simState.t >= gust.start && simState.t < gust.start + gust.duration) {
        wind.x += gust.x; wind.y += gust.y; wind.z += gust.z;
      }
      for (const axis of ['x', 'y', 'z']) {
        const force = sum * d[axis] + TASK.linearDrag * (wind[axis] - simState.vel[axis]);
        simState.vel[axis] += (force / params.mass - (axis === 'y' ? TASK.gravity : 0)) * dt;
        simState.pos[axis] += simState.vel[axis] * dt;
      }
      simState.t += dt;
      if (simState.pos.y > TASK.bodyHeight + 0.08) simState.airborne = true;
      if (Math.max(Math.abs(simState.att.roll), Math.abs(simState.att.pitch)) > TASK.flipAngle) simState.reason = 'flipped';
      if (Math.abs(simState.pos.x) + TASK.bodyRadius >= TASK.room.maxX || Math.abs(simState.pos.z) + TASK.bodyRadius >= TASK.room.maxZ || simState.pos.y + TASK.bodyHeight >= TASK.room.height) {
        if (norm(simState.vel) > TASK.contactCrashSpeed) simState.reason = 'wall or ceiling crash';
        simState.pos.x = clamp(simState.pos.x, TASK.room.minX + TASK.bodyRadius, TASK.room.maxX - TASK.bodyRadius);
        simState.pos.z = clamp(simState.pos.z, TASK.room.minZ + TASK.room.maxZ - TASK.bodyRadius);
      }
      if (simState.pos.y <= TASK.bodyHeight) {
        if (simState.airborne && (norm(simState.vel) > TASK.contactCrashSpeed || Math.max(Math.abs(simState.att.roll), Math.abs(simState.att.pitch)) > TASK.landingTilt * 2)) simState.reason = 'floor crash';
        simState.pos.y = TASK.bodyHeight; simState.vel.y = Math.max(0, simState.vel.y);
        simState.vel.x *= Math.exp(-12 * dt); simState.vel.z *= Math.exp(-12 * dt);
      }
      for (let i = 0; i < GATES.length; i++) {
        const gate = GATES[i], x = gate.centre.x;
        if ((old.x < x && simState.pos.x >= x) || (old.x > x && simState.pos.x <= x)) {
          const fraction = (x - old.x) / (simState.pos.x - old.x);
          const y = old.y + fraction * (simState.pos.y - old.y), z = old.z + fraction * (simState.pos.z - old.z);
          const dy = Math.abs(y - gate.centre.y), dz = Math.abs(z - gate.centre.z);
          const half = TASK.gateOpening / 2, outer = half + TASK.gateFrame;
          const fits = dy + TASK.bodyHeight <= half && dz + TASK.bodyRadius <= half;
          const overlapsFrame = dy <= outer + TASK.bodyHeight && dz <= outer + TASK.bodyRadius && !fits;
          if (overlapsFrame) simState.reason = 'gate frame collision';
          if (i === simState.gateIndex && old.x < x && simState.pos.x >= x && fits) simState.gateIndex++;
        }
      }
      const error = Math.hypot(simState.pos.x - PAD.centre.x, simState.pos.z - PAD.centre.z);
      if (simState.gateIndex === GATES.length && error <= TASK.landingRadius && simState.pos.y <= TASK.bodyHeight + 0.025 &&
          norm(simState.vel) < TASK.landingSpeed && Math.max(Math.abs(simState.att.roll), Math.abs(simState.att.pitch)) < TASK.landingTilt) simState.landedFor += dt;
      else simState.landedFor = 0;
      if (simState.landedFor >= TASK.landingHold && !simState.reason) simState.reason = 'landed';
    }
    return simState;
  };
}

let pass = 0, fails = [];
for (let seed = 0; seed < 500; seed++) {
  const step = makeStep(seed);
  let st;
  for (let i = 0; i < 1500; i++) {
    st = step();
    if (st.reason) break;
  }
  if (st.reason === 'landed') pass++;
  else fails.push({ seed, reason: st.reason || 'time limit', gates: st.gateIndex, t: +st.t.toFixed(3), y: +st.pos.y.toFixed(3), err: +Math.hypot(st.pos.x - PAD.centre.x, st.pos.z - PAD.centre.z).toFixed(3) });
}
console.log(`Passed ${pass}/500`);
console.log('Fails:', fails);
